description:
Build a store with types derived from one `Todo` interface:

```typescript
const PRIORITIES = ["low", "normal", "high"] as const;
type Priority = (typeof PRIORITIES)[number];

interface Todo { id: number; title: string; done: boolean; priority: Priority; notes?: string }
type NewTodo = Omit<Todo, "id" | "done">;         // what add takes
type TodoUpdate = Partial<Omit<Todo, "id">>;      // what update takes

class TodoStore {
  add(todo: NewTodo): Todo                        // ids 1, 2, 3...; done starts false
  update(id: number, changes: TodoUpdate): Todo   // throws Error("no todo <id>") for an unknown id
  list(filter?: Partial<Pick<Todo, "done" | "priority">>): Todo[]
}
```

- `add` throws an `Error` `bad priority <value>` when the priority is not one of `PRIORITIES` (data from outside may not follow the types), and trims the title.
- `update` returns the updated todo; the same priority check applies.
- `list` returns copies (changing them does not change the store), sorted by priority (`high` first) and then by id. Each property in the filter must match; an empty filter lists everything.

starter.solution.ts:
const PRIORITIES = ["low", "normal", "high"] as const;

class TodoStore {
  add(todo) { return todo; }
  update(id, changes) { return changes; }
  list(filter = {}) { return []; }
}

solution.solution.ts:
const PRIORITIES = ["low", "normal", "high"] as const;
type Priority = (typeof PRIORITIES)[number];

interface Todo { id: number; title: string; done: boolean; priority: Priority; notes?: string }
type NewTodo = Omit<Todo, "id" | "done">;
type TodoUpdate = Partial<Omit<Todo, "id">>;

function checkPriority(p: unknown): void {
  if (!(PRIORITIES as readonly unknown[]).includes(p)) throw new Error(`bad priority ${String(p)}`);
}

class TodoStore {
  #todos = new Map<number, Todo>();
  #nextId = 1;

  add(todo: NewTodo): Todo {
    checkPriority(todo.priority);
    const created: Todo = { ...todo, title: todo.title.trim(), id: this.#nextId++, done: false };
    this.#todos.set(created.id, created);
    return { ...created };
  }

  update(id: number, changes: TodoUpdate): Todo {
    const todo = this.#todos.get(id);
    if (!todo) throw new Error(`no todo ${id}`);
    if (changes.priority !== undefined) checkPriority(changes.priority);
    const updated: Todo = { ...todo, ...changes, id };
    this.#todos.set(id, updated);
    return { ...updated };
  }

  list(filter: Partial<Pick<Todo, "done" | "priority">> = {}): Todo[] {
    const rank = (p: Priority) => PRIORITIES.indexOf(p);
    return [...this.#todos.values()]
      .filter(t => (filter.done === undefined || t.done === filter.done) &&
                   (filter.priority === undefined || t.priority === filter.priority))
      .sort((a, b) => rank(b.priority) - rank(a.priority) || a.id - b.id)
      .map(t => ({ ...t }));
  }
}

unitTests:
test("adding", () => {
  const store = new TodoStore();
  const t = store.add({ title: "  Write tests ", priority: "high" });
  checkEq(t, { title: "Write tests", priority: "high", id: 1, done: false });
  checkEq(store.add({ title: "Nap", priority: "low", notes: "after lunch" }).id, 2);
  checkThrows(() => store.add({ title: "x", priority: "urgent" as never }));
});

test("updating", () => {
  const store = new TodoStore();
  store.add({ title: "a", priority: "normal" });
  checkEq(store.update(1, { done: true, priority: "high" }), { title: "a", priority: "high", id: 1, done: true });
  try { store.update(5, { done: true }); check(false, "should throw"); }
  catch (e) { checkEq((e as Error).message, "no todo 5"); }
  checkThrows(() => store.update(1, { priority: "meh" as never }));
  checkEq(store.update(1, { id: 9 } as never).id, 1);
});

test("listing with filters", () => {
  const store = new TodoStore();
  store.add({ title: "a", priority: "low" });
  store.add({ title: "b", priority: "high" });
  store.add({ title: "c", priority: "normal" });
  store.add({ title: "d", priority: "high" });
  store.update(4, { done: true });
  checkEq(store.list().map(t => t.title), ["b", "d", "c", "a"]);
  checkEq(store.list({ done: false }).map(t => t.title), ["b", "c", "a"]);
  checkEq(store.list({ priority: "high", done: true }).map(t => t.title), ["d"]);
  const copy = store.list()[0];
  copy.title = "changed";
  checkEq(store.list()[0].title, "b");
});

